import React, { useState, useMemo, useEffect } from 'react';

// --- Helper Icon Components ---
const InfoIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ color: '#6c757d', marginLeft: '8px', cursor: 'pointer' }}>
        <circle cx="12" cy="12" r="10"></circle>
        <line x1="12" y1="16" x2="12" y2="12"></line>
        <line x1="12" y1="8" x2="12.01" y2="8"></line>
    </svg>
);

const SaveIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ marginRight: '8px' }}>
        <path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z"></path>
        <polyline points="17 21 17 13 7 13 7 21"></polyline>
        <polyline points="7 3 7 8 15 8"></polyline>
    </svg>
);


// --- Main Base Allocation Tab Component ---
export default function BaseAllocationTab({ subjectCode, term }) {
    const [adminLoading, setAdminLoading] = useState(0); // Stored as a decimal (e.g., 0.01 for 1%)
    const [details, setDetails] = useState('');
    const [errors, setErrors] = useState({});

    // Calculate Base Allocation based on the formula: 3% + Administrative Loading
    const baseAllocation = useMemo(() => {
        const fixedBase = 0.03;
        // Proceed with calculation only if inputs are valid
        if (subjectCode && term && !errors.administrativeLoading) {
            return fixedBase + adminLoading;
        }
        // Fallback value if conditions aren't met
        return fixedBase;
    }, [adminLoading, errors.administrativeLoading, subjectCode, term]);

    // Run validation logic whenever relevant fields change
    useEffect(() => {
        const newErrors = {};

        // Rule 1: Administrative loading must be between 0% and 2%
        if (adminLoading < 0 || adminLoading > 0.02) {
            newErrors.administrativeLoading = 'Administrative loading must be between 0% and 2%.';
        }

        // Rule 2: Details are required if a claim is made
        if (adminLoading > 0 && !details.trim()) {
            newErrors.details = 'Details are required to justify the administrative loading claim.';
        }

        setErrors(newErrors);
    }, [adminLoading, details]);

    // Handler for the Administrative Loading input field
    const handleAdminLoadingChange = (e) => {
        const value = e.target.value;
        const numericValue = parseFloat(value);

        if (!isNaN(numericValue)) {
            setAdminLoading(numericValue / 100); // Convert percentage input to decimal for state
        } else {
            setAdminLoading(0);
        }
    };

    // Handler for saving data
    const handleSave = () => {
        // Check for errors before proceeding
        if (Object.keys(errors).length > 0) {
            alert("Please fix the validation errors before saving.");
            return;
        }
        // Log the data to be saved
        console.log("Saving data:", {
            baseAllocation: baseAllocation,
            administrativeLoading: adminLoading,
            details: details
        });
        alert("Workload details saved successfully!");
    };


    // Helper to format a decimal number into a percentage string (e.g., 0.03 -> "3.0%")
    const formatPercentage = (decimal) => (decimal * 100).toFixed(1);

    return (
        <div style={styles.container}>
            {/* --- Base Allocation Field (Read-Only) --- */}
            <div style={styles.formGroup}>
                <label htmlFor="baseAllocation" style={styles.label}>
                    Base Allocation
                    <InfoIcon />
                </label>
                <input
                    type="text"
                    id="baseAllocation"
                    value={`${formatPercentage(baseAllocation)}%`}
                    readOnly
                    style={styles.inputReadOnly}
                />
            </div>

            {/* --- Administrative Loading Field --- */}
            <div style={styles.formGroup}>
                <label htmlFor="adminLoading" style={styles.label}>
                    Administrative Loading
                    <InfoIcon />
                </label>
                <input
                    type="number"
                    id="adminLoading"
                    value={formatPercentage(adminLoading)}
                    onChange={handleAdminLoadingChange}
                    style={errors.administrativeLoading ? { ...styles.input, ...styles.inputError } : styles.input}
                    step="0.1"
                />
                {errors.administrativeLoading && <p style={styles.errorText}>{errors.administrativeLoading}</p>}
            </div>

            {/* --- Details Text Area --- */}
            <div style={styles.formGroup}>
                <label htmlFor="details" style={styles.label}>
                    Details
                </label>
                <textarea
                    id="details"
                    placeholder="If a claim is made, provide details."
                    value={details}
                    onChange={(e) => setDetails(e.target.value)}
                    style={errors.details ? { ...styles.textarea, ...styles.inputError } : styles.textarea}
                    rows="4"
                />
                {errors.details && <p style={styles.errorText}>{errors.details}</p>}
            </div>

            {/* --- Save Button --- */}
            <div style={styles.buttonContainer}>
                 <button onClick={handleSave} style={styles.saveButton}>
                    <SaveIcon />
                    Save
                </button>
            </div>
        </div>
    );
}

// --- Inline Styles for the Component ---
const styles = {
    container: {
        backgroundColor: '#fff',
        padding: '2rem',
        borderRadius: '8px',
        border: '1px solid #dee2e6',
    },
    formGroup: {
        marginBottom: '1.5rem',
    },
    label: {
        display: 'flex',
        alignItems: 'center',
        fontWeight: '500',
        color: '#343a40',
        marginBottom: '0.5rem',
    },
    input: {
        width: '200px',
        padding: '0.75rem',
        fontSize: '1rem',
        border: '1px solid #ced4da',
        borderRadius: '6px',
        transition: 'border-color 0.2s, box-shadow 0.2s',
    },
    inputReadOnly: {
        width: '200px',
        padding: '0.75rem',
        fontSize: '1rem',
        border: '1px solid #ced4da',
        borderRadius: '6px',
        backgroundColor: '#e9ecef',
        color: '#495057',
        cursor: 'not-allowed',
    },
    inputError: {
        borderColor: '#dc3545',
        boxShadow: '0 0 0 0.2rem rgba(220, 53, 69, 0.25)',
    },
    textarea: {
        width: '100%',
        padding: '0.75rem',
        fontSize: '1rem',
        border: '1px solid #ced4da',
        borderRadius: '6px',
        resize: 'vertical',
        fontFamily: 'inherit',
    },
    errorText: {
        color: '#dc3545',
        fontSize: '0.875rem',
        marginTop: '0.25rem',
    },
    buttonContainer: {
        display: 'flex',
        justifyContent: 'flex-start',
        marginTop: '1rem',
    },
    saveButton: {
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        padding: '0.6rem 1.5rem',
        fontSize: '1rem',
        fontWeight: '500',
        color: '#fff',
        backgroundColor: '#28a745',
        border: 'none',
        borderRadius: '6px',
        cursor: 'pointer',
        transition: 'background-color 0.2s',
    }
};
